type Movement = { kind: 'in' | 'out'; quantity: number };
export function movementDelta(item: Movement) {
  if (!Number.isSafeInteger(item.quantity) || item.quantity <= 0)
    throw new Error('양의 정수 수량이 필요합니다.');
  return item.kind === 'in' ? item.quantity : -item.quantity;
}
// 원장 기록과 잔고 갱신을 한 트랜잭션에서 수행합니다.

type Stock = { sku: string; onHand: number; reserved: number };
export function availableBySku(rows: Stock[], sku: string) {
  const item = rows.find(row => row.sku === sku);
  if (!item) return { state: 'unavailable' as const, quantity: 0 };
  const quantity = Math.max(0, item.onHand - item.reserved);
  return { state: quantity ? 'available' as const : 'sold-out' as const, quantity };
}

type ShipmentEvent = { id: string; occurredAt: number; receivedAt: number; status: string };
export function uniqueTimeline(events: ShipmentEvent[]) {
  const unique = new Map(events.map(event => [event.id, event]));
  return [...unique.values()].sort((a, b) => a.occurredAt - b.occurredAt
    || a.id.localeCompare(b.id));
}
