export function remainingToShip(ordered: number, cancelled: number, allocated: number[]) {
  const values = [ordered, cancelled, ...allocated];
  if (!values.every(n => Number.isSafeInteger(n) && n >= 0))
    throw new Error('수량 오류');
  const remaining = ordered - cancelled - allocated.reduce((a, b) => a + b, 0);
  if (remaining < 0) throw new Error('주문 수량을 초과한 배정');
  return remaining;
}

type ReturnedItem = { received: boolean; inspected: boolean; condition: 'resellable' | 'damaged' | 'unknown' };
export function mayRestock(item: ReturnedItem) {
  return item.received && item.inspected && item.condition === 'resellable';
}
